    def get_max_dose_rate(self):
        return get_object_text(integrity_objects.dQB_Edit_MaxDoseRate)

        # Function to set the stored beam energy to the desired value
    # Allows for the value to be "XLOW", "XMID" or "XHIGH" as previously supported by
    # QTP tests, without the need for having these energies setup on the machine.
    # If we receive one of these we translate it to what is supported on this
    # machine based on the rules for the ordering of the energies in the dropdown
    # DANGER - these may change in the future!!
    # ToT=Yes
    def set_energy(self, value):
        # Get the energies in the dropdown
        energies = self.get_energies_as_list()
        original_energy = value
        # Handle XLOW/XMID/XHIGH values
        # 3 possible scenarios
        #  1. XLOW - a low energy is always supported and it is always first in the list
        if value.upper() == "XLOW":
            value = energies[0]
        #  2. XMID - if there is a mid energy it is 3rd in the list. If it is not in the
        #     list then FFF or "CheckRG" will be 3rd instead or there will fewer than 3 entires.
        #     Licence generator doesn't allow XMID without XHIGH also
        if value.upper() == "XMID" and len(energies) > 2:
            if ("FFF" not in energies[2]) and ("Check RG" not in energies[2]):
                value = energies[2]
        #  3. XHIGH - if there is a high energy it is 2nd in the list. If it is not in the
        #     list then FFF or "Check RG" will be 2nd instead, or nothing at all
        if value.upper() == "XHIGH" and len(energies) > 1:
            if ("FFF" not in energies[1]) and ("Check RG" not in energies[1]):
                value = energies[1]

        # Select the energy
        try:
            container = integrity_objects.dQB_Energy_Combo
            sq.mouseClick(sq.waitForObject(container, 5))
            sq.mouseClick(sq.waitForObject({"container": container, "text": value}, 5))
        except Exception:            # If at first you don't succeed, try again!
            try:
                container = integrity_objects.dQB_Energy_Combo
                sq.mouseClick(sq.waitForObject(container, 5))
                sq.mouseClick(sq.waitForObject({"container": container, "text": value}, 5))
            except Exception:                # It's not in the list, caller will report and continue with next beam
                try:
                    container = {"type": "ComboBox", "x": 150, "y": 116}
                    sq.mousePress(sq.waitForObject(container, 5))
                    while sq.waitForObject({"container": container, "text": original_energy}).selected == False:
                        sq.nativeType("<Right>")
                    sq.nativeType("<Return>")

                except Exception as e:
                    return False
        return value

