    def set_mlc_shape(self, mlc_shape):
        if self.ready():
            self.tab_mlc()
            try:
                sq.mouseClick(sq.waitForObject("{id='220'  type='ComboBox'}"))
            except Exception:
                sq.mousePress(sq.waitForObject({"type": "ComboBox"}))
                sq.snooze(1)
            '''modified to try using keystrokes if list isn't accessible'''
            try:
                sq.mousePress(sq.waitForObject("{text='" + mlc_shape + "' type='ListItem'}", 1000))
                raise
            except Exception:
                sq.nativeType("<Home>")
                for n in range(1, 6):
                    sq.snooze(0.5)
                    try:
                        if sq.waitForObject("{id='220'  type='ComboBox'}")["text"] == mlc_shape:
                            sq.nativeType("<Return>")
                            break
                    except Exception:
                        if sq.waitForObject("{type='ComboBox'}")["text"] == mlc_shape:
                            sq.nativeType("<Return>")
                            break
                    sq.snooze(0.5)
                    sq.nativeType("<Right>")
